INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64950813', 64950813, 'analyze_legacy', 'Kab. Muara Enim', 'kabkota', 'Dinas Tanaman Pangan, Hortikultura dan Peternakan', 'Belanja Barang untuk DIjual/Diserahkan Kepada Masyarakat (Budidaya Ternak Ayam)', 'Barang', 'Pengadaan Langsung', 'Sumatera Selatan, Muara Enim (Kab.) | Sumatera Selatan, Muara Enim (Kab.) | Sumatera Selatan, Muara Enim (Kab.) | Sumatera Selatan, Muara Enim (Kab.) | Sumatera Selatan, Muara Enim (Kab.) | Sumatera Selatan, Muara Enim (Kab.)', 360000000, 'May 2026', 'APBD', 1, 1, '9.300 kg; 1.320 ekor;', 'Belanja Barang untuk Diserahkan kepada Masyarakat (Budidaya Ternak Ayam) terdiri dari ternak ayam sebanyak 1.320 ekor dan pakan ternak ayam sebanyak 9.300 kg dengan masing-masing penerima manfaat/poktan menerima 1 paket (Ternak ayam 220 ekor dan pakan ternak ayam 1.550 kg) rincian lokasi pengiriman ternak sebagai berikut : Poktan di Kel. Pasar I Kec. Muara Enim, Poktan di Kec. Lawang Kidul, Poktan di Kel. Tanjung Enim Kec. Lawang Kidul, Poktan di Kel. Tanjung Enim Selatan Kec. Lawang Kidul, Poktan di Desa Lubuk Raman Kec. Rambang Niru, Poktan di Desa Sukarame Kec. Rambang. KUALIFIKASI PENYEDIA : 1) Memiliki Nomor Induk Berusaha (NIB) aktif dan NPWP; 2) NIB memuat KBLI yang relevan dengan kegiatan perdagangan dan/atau pembibitan ungags; 3) Telah menyampaikan SPT Tahunan terakhir; 4) Memiliki alamat usaha yang jelas (milik sendiri atau sewa); 5) Memiliki pengalaman pengadaan ayam/unggas minimal 1 (satu) pekerjaan sejenis dalam kurun waktu 3 (tiga) tahun terakhir, baik di lingkungan pemerintah maupun swasta; 6) Memiliki minimal 1 (satu) tenaga teknis yang memahami budidaya unggas, dibuktikan dengan pengalaman kerja atau latar belakang pendidikan peternakan.', 'I. Ternak Ayam Buras. a. Jenis Ternak : Ayam KUB. b. Jumlah Ternak : 1.320 ekor. c. Umur Ternak : 4-5 bulan. d. Kondisi Fisik : Sehat dan Tidak Cacat. II. Pakan Konsentrat Ayam : - Bentuk butiran Halus (pakan jadi / konsentrat). - Kadar protein kasar minimal 30%. - Keluaran/Buatan : Pabrikan. - Kemasan dalam karung 30 kg atau 50 kg. III. Keterangan lain yang perlu : 1) Bebas dari cacat fisik, kondisi tubuh minimal sedang/tidak kurus dan dinyatakan sehat yang dibuktikan dengan Surat Keterangan Kesehatan Hewan (SKKH) dari dokter hewan/petugas berwenang atau Sertifikat Veteriner. 2) Surat Keterangan sudah divaksinasi ND AI dari Petugas Dinas Perternakan yang Berwenang Setempat/dari Daerah Asal Ternak 3) Persyaratan lainnya, meliputi : - Surat kesanggupan penggantian ternak yang mati disebabkan bukan karena kelalaian dari peternak selama 3 hari masa garansi. - Melengkapi Surat Keterangan Asal Ternak dari Daerah Setempat/dari Daerah asal Ternak.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1851242);
