INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64953021', 64953021, 'analyze_legacy', 'Kab. Muara Enim', 'kabkota', 'Dinas Tanaman Pangan, Hortikultura dan Peternakan', 'Belanja Barang untuk DIjual/Diserahkan Kepada Masyarakat (Budidaya Ternak Kambing)', 'Barang', 'Pengadaan Langsung', 'Sumatera Selatan, Muara Enim (Kab.) | Sumatera Selatan, Muara Enim (Kab.) | Sumatera Selatan, Muara Enim (Kab.) | Sumatera Selatan, Muara Enim (Kab.) | Sumatera Selatan, Muara Enim (Kab.) | Sumatera Selatan, Muara Enim (Kab.) | Sumatera Selatan, Muara Enim (Kab.) | Sumatera Selatan, Muara Enim (Kab.) | Sumatera Selatan, Muara Enim (Kab.) | Sumatera Selatan, Muara Enim (Kab.) | Sumatera Selatan, Muara Enim (Kab.)', 1260000000, 'May 2026', 'APBD', 1, 1, '280 ekor; 28 ekor;', 'URAIAN PEKERJAAN : Belanja Barang untuk Diserahkan kepada Masyarakat (Budidaya Ternak Kambing) terdiri dari ternak kambing betina sebanyak 280 ekor dan ternak kambing jantan 28 ekor dengan masing-masing penerima manfaat/poktan menerima 1 paket (Kambing betina 20 ekor dan Kambing jantan 2 ekor) rincian lokasi pengiriman ternak sebagai berikut : Poktan di Desa Kepur Kec. Muara Enim, Poktan di Desa Tanjung Lalang Kec. Tanjung Agung, 2 Poktan di Desa Tanjung Kec. Belimbing, Poktan di Desa Kuripan Kec. Empat Petulai Dangku, Poktan di Desa Kuripan Selatan Kec. Empat Petulai Dangku, Poktan di Desa Prabumenang Kec. Lubai Ulu, Poktan di Desa Jiwa Baru Kec. Lubai, Poktan di Desa Manunggal Jaya Kec. Rambang Niru, Poktan di Desa Suka Dana Kec. Sungai Rotan, Poktan di Desa Menanti Kec. Kelekar, 3 Poktan di Kel Gelumbang Kec. Gelumbang. B. KUALIFIKASI PENYEDIA : 1) Memiliki Nomor Induk Berusaha (NIB) aktif dan NPWP; 2) NIB memuat KBLI yang relevan dengan kegiatan perdagangan dan/atau pembibitan ternak kambing/domba; 3) Telah menyampaikan SPT Tahunan terakhir; 4) Memiliki alamat usaha yang jelas (milik sendiri atau sewa); 5) Memiliki pengalaman pengadaan ternak kambing/domba minimal 1 (satu) pekerjaan sejenis dalam kurun waktu 3 (tiga) tahun terakhir, baik di lingkungan pemerintah maupun swasta; 6) Memiliki minimal 1 (satu) tenaga teknis dengan latar belakang Dokter Hewan atau S1/D3 Peternakan, dibuktikan dengan ijazah dan identitas diri.', '1) Rumpun atau jenis ternak Kambing PE Persilangan dan/atau local; 2) Umur ternak kambing : Umur Ternak kambing jantan maupun betina maksimal 24 bulan berdasarkan hasil pemeriksaan gigi maksimal poel 1; 3) Tinggi Pundak Ternak (TP) : - Tinggi Pundak Betina minimal 65 cm - Tinggi Pundak Jantan minimal 75 cm; 4) Bebas dari cacat fisik, kondisi tubuh minimal sedang/tidak kurus dan dinyatakan sehat yang dibuktikan dengan Surat Keterangan Kesehatan Hewan (SKKH) dari dokter hewan/petugas berwenang atau Sertifikat Veteriner serta dengan melampirkan uji laboratorium (ELISA NSP) negatif PMK, negatif brucellosis (RBT dan CFT); 5) Penyedia mendistribusikan ternak sampai tempat penerima manfaa;t 6) Penyedia wajib memberikan garansi penggantian ternak kambing selama 7 (tujuh) hari kalender sejak serah terima, apabila terjadi kematian yang disebabkan oleh faktor kesehatan sebelum penyerahan, stres pengangkutan, atau penyakit bawaan, bukan akibat kelalaian penerima.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1853929);
