INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64954291', 64954291, 'analyze_legacy', 'Kab. Muara Enim', 'kabkota', 'Dinas Tanaman Pangan, Hortikultura dan Peternakan', 'Belanja Barang untuk DIjual/Diserahkan Kepada Masyarakat (Budidaya Ternak Sapi)', 'Barang', 'Pengadaan Langsung', 'Sumatera Selatan, Muara Enim (Kab.) | Sumatera Selatan, Muara Enim (Kab.) | Sumatera Selatan, Muara Enim (Kab.) | Sumatera Selatan, Muara Enim (Kab.) | Sumatera Selatan, Muara Enim (Kab.) | Sumatera Selatan, Muara Enim (Kab.) | Sumatera Selatan, Muara Enim (Kab.) | Sumatera Selatan, Muara Enim (Kab.) | Sumatera Selatan, Muara Enim (Kab.) | Sumatera Selatan, Muara Enim (Kab.) | Sumatera Selatan, Muara Enim (Kab.) | Sumatera Selatan, Muara Enim (Kab.) | Sumatera Selatan, Muara Enim (Kab.) | Sumatera Selatan, Muara Enim (Kab.) | Sumatera Selatan, Muara Enim (Kab.) | Sumatera Selatan, Muara Enim (Kab.) | Sumatera Selatan, Muara Enim (Kab.) | Sumatera Selatan, Muara Enim (Kab.) | Sumatera Selatan, Muara Enim (Kab.) | Sumatera Selatan, Muara Enim (Kab.) | Sumatera Selatan, Muara Enim (Kab.) | Sumatera Selatan, Muara Enim (Kab.) | Sumatera Selatan, Muara Enim (Kab.)', 5184000000, 'May 2026', 'APBD', 1, 1, '270 ekor; 27 ekor;', 'A.URAIAN PEKERJAAN : Belanja Barang untuk Diserahkan kepada Masyarakat (Budidaya Ternak Sapi) terdiri dari ternak sapi betina sebanyak 270 ekor betina dan ternak sapi jantan 27 ekor dengan masing-masing penerima manfaat/poktan menerima 1 paket (sapi betina 10 ekor dan sapi jantan 1 ekor) rincian lokasi pengiriman ternak sebagai berikut : 2 Poktan di Desa Muara Harapan Kec. Muara Enim , Poktan di Kel. Air Lintang Kec. Muara Enim, Poktan di Desa Tegal Rejo Kec. Lawang Kidul, Poktan di Desa Tanjung Muning Kec. Gunung Megang, Poktan di Desa Teluk Lubuk Kec. Belimbing, Poktan di Desa Cinta Kasih Kec. Belimbing, Poktan di Desa Dalam Kec. Belimbing, 2 Poktan di Desa Bulang Kec. Belimbing, Poktan di Desa Banuayu Kec. Empat Petulai Dangku, Poktan di Desa Sumber Asri Kec. Lubai Ulu, Poktan di Desa Pagar Dewa Kec. Lubai Ulu, Poktan di Desa Prabumenang Kec. Lubai Ulu, Poktan di Desa Jemenang Kec. Rambang Niru, Poktan di Desa Gemawang Kec. Rambang Niru, Poktan di Desa Sukarami Kec. Sungai Rotan, Poktan di Desa Menanti Kec. Kelekar, Poktan di Desa Babat Kec. Belida Darat, Poktan di Desa Karang Endah Kec.Gelumbang, Poktan di Desa Tambangan Kelekar Kec. Gelumbang, 2 Poktan di Desa Talang Taling Kec. Gelumbang, Poktan di Desa Sukamenang Kec. Gelumbang, Poktan di Desa Putak Kec. Gelumbang, Poktan di Desa Harapan Mulia Kec. Muara Belida. B. KUALIFIKASI PENYEDIA : 1) Memiliki Nomor Induk Berusaha (NIB) aktif dan NPWP; 2) NIB memuat KBLI yang relevan dengan kegiatan perdagangan dan/atau pembibitan ternak sapi; 3) Telah menyampaikan SPT Tahunan terakhir; 4) Memiliki alamat usaha yang jelas (milik sendiri atau sewa); 5) Memiliki pengalaman pengadaan ternak sapi minimal 1 (satu) pekerjaan sejenis dalam kurun waktu 3 (tiga) tahun terakhir, baik di lingkungan pemerintah maupun swasta; 6) Memiliki minimal 1 (satu) tenaga teknis dengan latar belakang Dokter Hewan atau S1/D3 Peternakan, dibuktikan dengan ijazah dan identitas diri.', '1) Rumpun Sapi bali; 2) Umur ternak Sapi Bali : - Ternak Sapi Bali Betina umur maksimal 36 bulan berdasarkan hasil pemeriksaan gigi maksimal poel 2 - Ternak Sapi Bali Jantan umur maksimal 42 bulan berdasarkan hasil pemeriksaan gigi maksimal poel 3; 3) Tinggi Pundak Ternak (TP) : - Ternak Sapi Bali Betina dengan Tinggi Pundak minimal 105 - Ternak Sapi Bali Jantan dengan Tinggi Pundak minimal 115; 4) Mempunyai reproduksi normal yang dinyatakan dengan Surat Keterangan Status Reproduksi (SKSR) dari dikter hewan/petugas berwenang; 5) Bebas dari cacat fisik dan dinyatakan sehat yang dibuktikan dengan Surat Keterangan Kesehatan Hewan (SKKH) dari dokter hewan/petugas berwenang yang menyatakan bebas Penyakit PMK, LSD, Jembrana, Brucellosis, Antrax, Surra dan Septicaemia Epizootica (SE); 6) Persyaratan lainnya, meliputi : − Surat kesanggupan penggantian ternak yang mati disebabkan bukan karena kelalaian dari peternak selama 7 hari masa garansi. - Melengkapi Surat Keterangan Asal Ternak dari Daerah Setempat/dari Daerah asal Ternak; 7) Seleksi ternak menjadi tanggung jawab penyedia barang dan jasa, dilengkapi dengan surat ketererangan sehat dari dokter hewan/petugas berwenang setempat, dengan melampirkan hasil uji laboratorium negatif Jembrana (PCR) negatif PMK (PCR), negatif LSD (PCR) dan negatif brucellosis; 8) ternak Sudah di vaksin PMK sebanyak 2 (dua) kali dan vaksin Jembrana sesuai ketentuan yang berlaku.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1854199);
