INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64931031', 64931031, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan Penyusunan Kajian Penguatan Tata Kelola dan Produk Hukum lingkup Sinergi dan Tata Kelola Perencanaan Pembangunan', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 66763638, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '6', 'Membantu Direktur dalam melakukan pendampingan penyusunan Rancangan Awal Rencana Kerja Pemerintah, Rancangan Rencana Kerja Pemerintah, Rencana Kerja Pemerintah, dan Pemutakhiran RKP Tahun 2027 termasuk namun tidak terbatas pada Pedoman, Peraturan Menteri PPN/Kepala Bappenas, Peraturan Presiden dan Peraturan Kebijakan Teknis, serta substansi dan administrasi peraturan perundang-undangan dan peraturan kebijakan terkait. Melakukan reviu hukum terhadap kebijakan, MoU, nota kesepahaman, berita acara kesepakatan, dan dokumen terkait yang mendukung pelaksanaan RKP. Memberikan pendampingan hukum dalam proses penyusunan RKP, termasuk konsultasi hukum terhadap kegiatan prioritas nasional. Membantu harmonisasi dokumen hukum antar direktorat dan antarkementerian/lembaga dalam kerangka penyusunan RKP.', '1. Pendidikan konsultan minimal S1 bidang hukum, baik di dalam ataupun di luar negeri dan dapat dibuktikan dengan Ijazah atau dokumen resmi kelulusan atau sertifikat kelulusan; 2. Memiliki pengalaman baik di lingkungan pemerintah maupun swasta, termasuk pengalaman subkontrak, dan dapat dibuktikan dengan surat kontrak dan atau surat pengalaman; 3. Memiliki pengalaman minimal 3 (tiga) tahun dalam menyusun peraturan perundang-undangan dan/atau peraturan kebijakan di lingkungan pemerintah. 4. Diutamakan memiliki sertifikat pelatihan perancangan peraturan perundangundangan yang diselenggarakan oleh kementerian yang menyelenggarakan urusan di bidang hukum. 5. Bukan berstatus ASN aktif dan tidak sedang terikat kontrak permanen dengan pekerjaan lain; 6. Tidak pernah diberhentikan dengan tidak terhormat sebagai Pegawai/ASN/Konsultan Individu; 7. Diutamakan Jasa Konsultan dalam negeri (dibuktikan dengan identitas kewarganegaraan Indonesia seperti Kartu Tanda Penduduk) 8. Mempunyai status valid keterangan Wajib Pajak berdasarkan Hasil Konfirmasi Status Wajib Pajak (KSWP); 9. Memiliki bukti potong pajak atas penghasilan tertinggi pada institusi/Lembaga pekerjaan sebelumnya atau bukti lapor SPT pajak tahunan terakhir; 10.Bekerja berdasarkan output keluaran (Output-Based), dan memiliki komitmen untuk hadir secara fisik apabila dibutuhkan dan melakukan perjalanan apabila dibutuhkan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1858537);
